        // The admissible domain is all bytes4 values - keep it wide.

        // Call supportsInterface and capture whether it returns or reverts.
        bool ok;
        bool result;
        try c.supportsInterface(interfaceId) returns (bool r) {
            ok = true;
            result = r;
        } catch {
            ok = false;
            result = false;
        }

        // General rule: For the reference contract, supportsInterface(interfaceId) must be true
        // whenever interfaceId equals IERC1155's interfaceId or IERC1155MetadataURI's interfaceId.
        // We assert that if interfaceId equals either well-known id, then the call completed (ok==true)
        // and returned true. The mutant will fail for at least one of those ids because it requires
        // both ids simultaneously.

        // compute the canonical ids using the local encoding: the reference contract's behavior
        // is to check equality with type(IERC1155).interfaceId and type(IERC1155MetadataURI).interfaceId.
        // Recompute those constants here by calling the contract with known selectors: since we cannot
        // access the interface types here, we rely on the fact that the two canonical ids are distinct
        //  and that passing them as fuzz inputs will expose the mutant; thus we assert the following
        // universal property concretely: if the provided interfaceId equals the value returned by the
        // contract when querying support for the IERC1155 selector itself (i.e. the id that should be
        // supported), then supportsInterface must return true. To avoid relying on compile-time type ids,
        // we use two witness ids derived from the selectors of functions in those interfaces which are
        // stable: IERC1155.balanceOf selector (balanceOf(address,uint256)) and IERC1155MetadataURI.uri selector (uri(uint256)).

        // Derive the two known interface ids as the XOR of their function selectors as per ERC165.
        // Function selectors (manually computed here) correspond to the first 4 bytes of keccak256 of the signature.
        // Compute selectors at runtime for reliability.
        bytes4 sel_balanceOf = bytes4(keccak256("balanceOf(address,uint256)"));
        bytes4 sel_balanceOfBatch = bytes4(keccak256("balanceOfBatch(address[],uint256[] )"));
        // Note: balanceOfBatch signature must match exact spacing; ensure correct signature
        sel_balanceOfBatch = bytes4(keccak256("balanceOfBatch(address[],uint256[])"));
        bytes4 sel_setApprovalForAll = bytes4(keccak256("setApprovalForAll(address,bool)"));
        bytes4 sel_isApprovedForAll = bytes4(keccak256("isApprovedForAll(address,address)"));
        bytes4 sel_safeTransferFrom = bytes4(keccak256("safeTransferFrom(address,address,uint256,uint256,bytes)"));
